DROP TABLE IF EXISTS `incidents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `incidents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `category` enum('security_breach','system_outage','data_loss','malware','unauthorized_access','phishing','ddos','other') NOT NULL DEFAULT 'other',
  `severity` enum('low','medium','high','critical') NOT NULL DEFAULT 'medium',
  `status` enum('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open',
  `reported_by_id` int(11) NOT NULL,
  `assigned_to_id` int(11) DEFAULT NULL,
  `resolution_notes` text DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `FK_3f25378f332890bea45df59b5e1` (`reported_by_id`),
  KEY `FK_9036c3f88d411562af1241e404b` (`assigned_to_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `incidents` WRITE;
/*!40000 ALTER TABLE `incidents` DISABLE KEYS */;
/*!40000 ALTER TABLE `incidents` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `issuances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `issuances` (
  `id` varchar(36) NOT NULL,
  `issuance_number` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `issuance_type` varchar(80) DEFAULT NULL,
  `applicability_scope` text DEFAULT NULL,
  `relevance_notes` text DEFAULT NULL,
  `is_amendment` tinyint(1) NOT NULL DEFAULT 0,
  `amended_issuance_number` varchar(100) DEFAULT NULL,
  `ict_amendment_notes` text DEFAULT NULL,
  `issuing_authority` varchar(100) NOT NULL,
  `issue_date` date NOT NULL,
  `effectivity_date` date DEFAULT NULL,
  `source_url` varchar(500) DEFAULT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `attachment_file_name` varchar(255) DEFAULT NULL,
  `attachment_mime_type` varchar(120) DEFAULT NULL,
  `attachment_blob` longblob DEFAULT NULL,
  `attachment_uploaded_at` datetime DEFAULT NULL,
  `binding_nature` varchar(60) DEFAULT NULL,
  `adoption_basis` text DEFAULT NULL,
  `applicable_provisions` text DEFAULT NULL,
  `compliance_obligations` text DEFAULT NULL,
  `required_evidence` text DEFAULT NULL,
  `evidence_location` text DEFAULT NULL,
  `process_owner` varchar(160) DEFAULT NULL,
  `frequency_cadence` varchar(80) DEFAULT NULL,
  `compliance_status` varchar(40) DEFAULT NULL,
  `gap_summary` text DEFAULT NULL,
  `action_required` text DEFAULT NULL,
  `target_date` date DEFAULT NULL,
  `last_review_date` date DEFAULT NULL,
  `quarterly_readiness` varchar(40) DEFAULT NULL,
  `q1_compliance_status` varchar(40) DEFAULT NULL,
  `q2_compliance_status` varchar(40) DEFAULT NULL,
  `q3_compliance_status` varchar(40) DEFAULT NULL,
  `q4_compliance_status` varchar(40) DEFAULT NULL,
  `register_added_at` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_2feaf6362fee95952b67c779aa` (`issuance_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `issuances` WRITE;
/*!40000 ALTER TABLE `issuances` DISABLE KEYS */;
INSERT INTO `issuances` VALUES
('issuance-001','RA-10173','Data Privacy Act of 2012','Personal data protection law.','law','Applies to ICT owners, compliance reviewers, system custodians, records handlers, procurement focal staff, and service process owners. Covers governance policy creation, day-to-day control operations, incident and exception handling, lifecycle monitoring, and audit evidence management across planning, implementation, and continuous improvement phases. Includes obligations for system access governance, data handling boundaries, records retention, coordination with oversight offices, and evidence traceability for legal and audit inspection.','Provides enforceable legal obligations that define minimum compliance expectations, accountability boundaries, and consequences for non-compliance. Used as the primary basis for control mapping, policy updates, compliance attestations, and supersession checks when newer laws amend or replace prior legal requirements. Legal issuances should be interpreted as source-of-truth requirements for mandatory controls, and every implementation decision should be traceable to a specific provision, responsible office, affected process, and supporting compliance evidence.',0,NULL,NULL,'Congress of the Philippines','2012-08-15','2012-09-08','https://www.officialgazette.gov.ph/2012/08/15/republic-act-no-10173/',1,'2026-03-03 16:50:00.000000','2026-03-03 16:50:00.525665',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
